import {test, expect} from 'bun:test';
import {run} from './interpreter.js';
test('żółw rysuje odcinek w kierunku północy',()=>{expect(run('np 10','2d')).toEqual({segments:[{from:[0,0,0],to:[0,10,0],color:'#16866a',width:3}],error:null})});
EOF
bun test"

